-- Pipeline METADATA tables for MySQL. Generated by scripts/export_ddl.py - do not edit by hand.
-- The framework also creates these automatically (CREATE TABLE IF NOT EXISTS semantics).
-- Business tables are created from the data on first load.

CREATE TABLE IF NOT EXISTS etl_pipeline_runs (
	execution_id VARCHAR(36) NOT NULL, 
	pipeline_name VARCHAR(64) NOT NULL, 
	source_type VARCHAR(16), 
	status VARCHAR(24) NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME, 
	duration_seconds FLOAT, 
	extracted_count INTEGER NOT NULL, 
	transformed_count INTEGER NOT NULL, 
	valid_count INTEGER NOT NULL, 
	invalid_count INTEGER NOT NULL, 
	loaded_count INTEGER NOT NULL, 
	failed_batch_count INTEGER NOT NULL, 
	schema_drift_status VARCHAR(24), 
	error_message TEXT, 
	report_json LONGTEXT, 
	PRIMARY KEY (execution_id)
);
CREATE INDEX ix_runs_pipeline_start ON etl_pipeline_runs (pipeline_name, start_time);
CREATE INDEX ix_runs_status ON etl_pipeline_runs (status);

CREATE TABLE IF NOT EXISTS etl_schema_drift_history (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	pipeline_name VARCHAR(64) NOT NULL, 
	execution_id VARCHAR(36) NOT NULL, 
	previous_version INTEGER, 
	status VARCHAR(24) NOT NULL, 
	decision VARCHAR(10) NOT NULL, 
	report_json LONGTEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE INDEX ix_drift_pipeline_created ON etl_schema_drift_history (pipeline_name, created_at);

CREATE TABLE IF NOT EXISTS etl_schema_metadata (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	pipeline_name VARCHAR(64) NOT NULL, 
	version INTEGER NOT NULL, 
	execution_id VARCHAR(36) NOT NULL, 
	schema_json LONGTEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_schema_pipeline_version UNIQUE (pipeline_name, version)
);

CREATE TABLE IF NOT EXISTS etl_watermarks (
	pipeline_name VARCHAR(64) NOT NULL, 
	watermark_column VARCHAR(64) NOT NULL, 
	watermark_value VARCHAR(64) NOT NULL, 
	execution_id VARCHAR(36) NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (pipeline_name)
);

CREATE TABLE IF NOT EXISTS etl_batch_log (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	execution_id VARCHAR(36) NOT NULL, 
	pipeline_name VARCHAR(64) NOT NULL, 
	batch_number INTEGER NOT NULL, 
	row_count INTEGER NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	attempts INTEGER NOT NULL, 
	error_message TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_batch_execution_number UNIQUE (execution_id, batch_number), 
	FOREIGN KEY(execution_id) REFERENCES etl_pipeline_runs (execution_id)
);

CREATE TABLE IF NOT EXISTS etl_data_quality_results (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	execution_id VARCHAR(36) NOT NULL, 
	check_name VARCHAR(160) NOT NULL, 
	level VARCHAR(10) NOT NULL, 
	unit VARCHAR(16) NOT NULL, 
	total_checked INTEGER NOT NULL, 
	passed INTEGER NOT NULL, 
	failed INTEGER NOT NULL, 
	failure_pct FLOAT NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	error_details TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(execution_id) REFERENCES etl_pipeline_runs (execution_id)
);
CREATE INDEX ix_dq_check_status ON etl_data_quality_results (check_name, status);
CREATE INDEX ix_dq_execution ON etl_data_quality_results (execution_id);

CREATE TABLE IF NOT EXISTS etl_quarantined_records (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	execution_id VARCHAR(36) NOT NULL, 
	pipeline_name VARCHAR(64) NOT NULL, 
	stage VARCHAR(16) NOT NULL, 
	reason TEXT NOT NULL, 
	record_json LONGTEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(execution_id) REFERENCES etl_pipeline_runs (execution_id)
);
CREATE INDEX ix_quarantine_execution ON etl_quarantined_records (execution_id);
CREATE INDEX ix_quarantine_pipeline_stage ON etl_quarantined_records (pipeline_name, stage);
